export const UI_KEY='beargame.chapters.ui.v1';
export const LEASE_KEY='beargame.chapters.active-tab.v1';
export const LEGACY_KEY='beargame.save.v1';
export const regions=Object.freeze([
 {id:'village',name:'林间家园',buildings:['hive','hut','library','barn','pasture','logHouse','warehouse']},
 {id:'woodland',name:'山边工坊',buildings:['mine','workshop','smelter','lumberMill']},
]);
export const esc=(s='')=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fmt(value,digits=0){const n=Number(value)||0;if(Math.abs(n)>=1e6)return (n/1e6).toFixed(2)+'M';if(Math.abs(n)>=10000)return (n/1000).toFixed(1)+'k';return n.toLocaleString('zh-CN',{maximumFractionDigits:digits});}
export const known=c=>!!c&&(c.unlocked===true||c.visible===true||c.owned>0||c.completed===true||c.assigned>0);
export function visibleRegions(vm){
 const owned=id=>vm.buildings?.some(c=>c.id===id&&c.owned>0),active=regions.slice(1).filter(r=>r.buildings.filter(owned).length>=2);
 const folded=regions.slice(1).filter(r=>!active.includes(r)).flatMap(r=>r.buildings.filter(owned));
 return [{...regions[0],buildings:[...regions[0].buildings,...folded]},...active];
}
export function chapterComplete(vm){return !!vm.science?.some(c=>c.id==='construction'&&c.completed)&&['logHouse','warehouse','lumberMill'].every(id=>vm.buildings?.some(c=>c.id===id&&c.owned>0));}
export function lotPosition(index){return {x:index%2?72:28,y:155+Math.floor(index/2)*225+(index%2?72:0)};}
export function sceneLayout(vm,regionId){
 const groups=visibleRegions(vm),region=groups.find(r=>r.id===regionId)||groups[0];let height=460;
 const buildings=region.buildings.map((id,index)=>({card:vm.buildings?.find(c=>c.id===id),index})).filter(({card})=>card?.owned>0).map(({card,index})=>{const pos=lotPosition(index);height=Math.max(height,pos.y+150);return {card,index,...pos};});
 return {region,buildings,height};
}
const jobOutput={woodcutter:'wood',farmer:'honey',scholar:'science',hunter:'manpower',miner:'minerals'};
const jobPlace={woodcutter:['lumberMill','hut','logHouse'],farmer:['hive','pasture'],scholar:['library'],hunter:['hut','logHouse'],miner:['mine']};
// Keep every represented occupation in its own footprint. Resting bears use
// a clearing rather than inheriting a hut's working position. Coordinates only
// depend on buildings/jobs and viewport geometry, never production or animation.
export function sceneActors(snapshot,regionId,{width=336,viewportWidth=width,paused=false}={}){
 const layout=sceneLayout(snapshot,regionId),narrow=viewportWidth<=350;
 const body={width:narrow?62:72,height:narrow?79:90},gap=10;
 const bounds=(x,y,w=body.width,h=body.height)=>({left:x*width/100-w/2,right:x*width/100+w/2,top:y-h/2,bottom:y+h/2});
 const overlaps=(a,b)=>a.left<b.right+gap&&a.right+gap>b.left&&a.top<b.bottom+gap&&a.bottom+gap>b.top;
 const buildingWidth=Math.min(width*(narrow?.44:.39),230),buildingHeight=viewportWidth>=700?190:narrow?163:176;
 const buildingBounds=layout.buildings.map(p=>bounds(p.x,p.y,buildingWidth,buildingHeight));
 // Name badges sit at the bottom of each building button. Leave their whole
 // clickable label clear while still allowing a worker beside its workplace.
 const labelBounds=layout.buildings.map(p=>bounds(p.x,p.y+buildingHeight/2-15,Math.min(buildingWidth,Math.max(110,(p.card.name.length+(p.card.toggleable&&!p.card.enabled?5:0))*12+22)),30));
 const representatives=new Map();for(const bear of snapshot.bears?.individuals||[]){const job=bear.job||'idle';if(!representatives.has(job))representatives.set(job,bear);}
 const actors=[],occupied=[];let height=layout.height;
 const place=(bear,job,p,resting=false)=>{
  let position;
  if(resting){
   // The upper-right clearing is free of the first building's hit target at
   // every supported width. Scan other clearings if a worker is already there.
   for(let y=body.height/2+10;!position;y+=body.height+gap)for(const x of [72,28,50]){
    const box=bounds(x,y);if(box.left<8||box.right>width-8||[...buildingBounds,...occupied].some(other=>overlaps(box,other)))continue;
    position={x,y};break;
   }
  }else{
   const origin=p.x*width/100,candidates=[];
   for(let row=0;row<=12;row++)for(const sign of row?[1,-1]:[1])for(const offset of [0,body.width+gap,-body.width-gap]){
    const x=(origin+offset)/width*100,y=p.y+row*(body.height+gap)*sign,box=bounds(x,y);
    if(box.left<8||box.right>width-8||box.top<8)continue;
    candidates.push({x,y,distance:offset**2+(y-p.y)**2});
   }
   position=candidates.sort((a,b)=>a.distance-b.distance).find(c=>![...occupied,...labelBounds].some(other=>overlaps(bounds(c.x,c.y),other)));
  }
  if(!position)position={x:50,y:height+body.height/2+gap};
  position.x=Math.round(position.x*1e6)/1e6;
  const box=bounds(position.x,position.y);occupied.push(box);height=Math.max(height,box.bottom+20);
  const output=getResource(snapshot,jobOutput[job]),working=!!jobOutput[job]&&!paused&&(output.grossRate??output.rate)>0&&(output.max==null||output.value<output.max);
  actors.push({bear,job,...position,working,count:job==='idle'?(snapshot.bears.free||1):(snapshot.bears.jobs?.[job]||1),bounds:box});
 };
 for(const job of ['farmer','woodcutter','scholar','hunter','miner']){
  const bear=representatives.get(job);if(!bear)continue;
  const lot=(jobPlace[job]||[]).map(id=>layout.buildings.find(p=>p.card.id===id)).find(Boolean);
  if(!lot&&layout.region.id!=='village')continue;
  const p=lot||{x:46,y:300};place(bear,job,{x:p.x+(p.x<50?17:-17),y:p.y+24+(job==='hunter'?50:0)});
 }
 if(layout.region.id==='village'&&representatives.has('idle'))place(representatives.get('idle'),'idle',null,true);
 return {actors,height,buildingBounds,labelBounds};
}
const bearLines={woodcutter:'这段木头的年轮，像一圈圈小路。',farmer:'轻一点，小蜜蜂也在忙呢。',scholar:'用一片叶子作书签，正合适。',hunter:'森林里，每条小路都有故事。',miner:'这块石头里，有一道亮亮的纹路。',idle:'这朵云，有点像一罐蜂蜜。'};
const paths={home:'M3 11 12 3l9 8M5 9v12h14V9M9 21v-8h6v8',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16',close:'m6 6 12 12M18 6 6 18',more:'M4 12h.01M12 12h.01M20 12h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',box:'m3 6 9-3 9 3v13l-9 3-9-3zM3 6l9 3 9-3M12 9v13',arrow:'m9 5 7 7-7 7',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01',save:'M5 3h13l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',pause:'M8 4v16M16 4v16',play:'m7 4 13 8-13 8z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v3M12 20v3M1 12h3M20 12h3',leaf:'M4 19C0 8 10 1 21 3c1 12-6 20-17 16ZM4 19 16 8'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
function image(kind,id,cls='',pose){let src=art[kind]?.[id];if(src&&typeof src==='object')src=src[pose||'ready'];if(!src)return '';return `<img class="${cls}" src="${esc(src)}" alt="" draggable="false">`;}
function buildingImage(c,cls=''){const threshold={hive:5,hut:3,library:3,barn:3,lumberMill:3,workshop:3,warehouse:3};return image(c.owned>=(threshold[c.id]||Infinity)&&art.growth?.[c.id]?'growth':'buildings',c.id,cls);}
const artFor=(c,section)=>section==='buildings'?buildingImage(c):section==='science'?image('research',c.id):image('resources',section==='workshop'?(c.costs?.some(x=>x.id==='iron')?'iron':'science'):c.id);
const cardType=(c,section)=>c.type||({buildings:'build',science:'research',workshop:'upgrade',crafts:'craft',jobs:'assign'})[section];
const signed=n=>(n>0?'+':'')+fmt(n,2);
const getResource=(vm,id)=>vm.resources?.find(r=>r.id===id)||{id,value:0,rate:0,max:null,name:id};
export function batchSummary(c,amount='max'){
 const costs=c.costs||[];let count=amount==='max'?Math.min(1000000,...costs.filter(x=>x.value>0).map(x=>Math.floor((x.owned+1e-9)/x.value))):Number(amount);
 if(!Number.isFinite(count))count=1;count=Math.max(0,count);return {count,costs:costs.map(x=>({...x,value:x.value*count}))};
}

let app,dialogRoot,game,vm,readOnly=false,storageIssue='',loadBlocked=false,settling=false,settlementFailed=false;
let loading=false,settlementFailureKind='',settlementFailureMessage='';
let tabId,leaseTimer,tickTimer,lastTick=0,lastSave=0,hiddenAt=null,toastTimer,dialog=null,parentDialog=null,returnFocus=null,dialogHistory=false,booted=false;
let settings={reducedMotion:false},completionWasShown=false;
const ui={page:'home',region:'village',buildChoice:'hive',researchTab:'science',queuePage:0,queueKey:'',revealBuilding:null,scrolls:{},pageKey:'',structureKey:'',hudKey:'',navKey:''};
function now(){return Date.now();}
function readStorage(key){try{return localStorage.getItem(key);}catch{storageIssue='浏览器无法读取存档。已停止推进，请检查存储设置。';return null;}}
function writeStorage(key,value){try{localStorage.setItem(key,value);return true;}catch{storageIssue='浏览器无法保存进度。已停止推进，请导出当前存档。';return false;}}
function lease(){try{return JSON.parse(readStorage(LEASE_KEY)||'null');}catch{return null;}}
function ownsLease(){return lease()?.id===tabId;}
function claim(force=false){const current=lease();if(storageIssue){readOnly=true;return false;}if(!force&&current?.id!==tabId&&current?.until>now()){readOnly=true;return false;}if(!writeStorage(LEASE_KEY,JSON.stringify({id:tabId,until:now()+7000}))){readOnly=true;return false;}readOnly=!ownsLease();return !readOnly;}
const safeStorage={getItem:key=>{let result;try{result=localStorage.getItem(key);}catch(error){storageIssue='浏览器无法读取存档。已停止推进，原数据不会被覆盖。';throw error;}return result;},setItem:(key,value)=>{if(!ownsLease()||readOnly||loadBlocked)throw Error('当前页面没有保存权限。');if(!writeStorage(key,value))throw Error(storageIssue);},removeItem:key=>{if(!ownsLease()||readOnly||loadBlocked)throw Error('当前页面没有保存权限。');localStorage.removeItem(key);}};
function canAct(){return !!game&&!loading&&!readOnly&&!storageIssue&&!loadBlocked&&!settling&&!settlementFailed&&ownsLease();}
function stopProgress(message,kind){settlementFailed=true;settlementFailureKind=kind;settlementFailureMessage=String(message||(kind==='offline'?'离线结算中断，原有进度已保留。':'时间推进中断，原有进度已保留。'));}
function stopped(){return readOnly||storageIssue||loadBlocked||settling||settlementFailed||vm?.settings?.paused;}
function notify(text,duration=3500){const toast=document.querySelector('#toast');if(!toast)return;clearTimeout(toastTimer);toast.textContent=text;toast.classList.add('visible');toastTimer=setTimeout(()=>toast.classList.remove('visible'),duration);}
function save(){if(!canAct())return {ok:false,message:storageIssue||'当前页面暂停保存，原存档不会被覆盖。'};const result=game.save();lastSave=now();if(result.ok===false){storageIssue=result.message||'存档保存失败，请导出备份。';renderStatus();}return result;}
function reloadGame(){ui.revealBuilding=null;game=loadGame({storage:safeStorage,deferOffline:true});vm=game.snapshot();settlementFailed=false;settlementFailureKind='';settlementFailureMessage='';loadBlocked=vm.saveStatus?.ok===false;lastTick=now();lastSave=now();return vm;}
function rates(r){return vm.settings?.paused?'已暂停':readOnly?'只读':settling?'结算中':storageIssue||loadBlocked||settlementFailed?'已停止':signed(r.rate)+'/秒';}
function writeText(selector,value,root=app){const el=root?.querySelector(selector);if(el&&el.textContent!==String(value))el.textContent=value;}
function queueOrderKey(snapshot){return JSON.stringify(snapshot.queue?.items?.map(c=>[c.type,c.id,c.amount])||[]);}
function activeKey(){const el=document.activeElement;if(!el?.dataset)return null;const key=[...Object.entries(el.dataset)].filter(([key])=>['nav','act','id','detail','command','buildChoice','researchTab','region','bear','amount','queuePage'].includes(key));if(['queueRemove','queueUp','queueDown','queueClear'].includes(el.dataset.act))key.queueOrder=ui.queueKey;return key;}
function restoreFocus(key){if(!key?.length)return;if(Object.hasOwn(key,'queueOrder')&&key.queueOrder!==queueOrderKey(vm)){app?.querySelector('[data-queue-heading]')?.focus({preventScroll:true});return;}[...document.querySelectorAll('button')].find(el=>key.every(([k,v])=>el.dataset[k]===v))?.focus({preventScroll:true});}
function pageKey(){return [ui.page,ui.region,ui.buildChoice,ui.researchTab,ui.page==='queue'?ui.queuePage:0].join(':');}
function structuralKey(){return JSON.stringify([vm.buildings?.filter(known).map(c=>[c.id,c.owned,c.enabled]),vm.science?.filter(known).map(c=>[c.id,c.completed]),vm.workshop?.filter(known).map(c=>[c.id,c.completed]),vm.crafts?.filter(known).map(c=>c.id),vm.jobs?.filter(known).map(c=>[c.id,c.assigned]),vm.bears?.value,stopped(),chapterComplete(vm),!!vm.observation,vm.queue?.items?.map(c=>[c.type,c.id,c.amount]),vm.queue?.options?.map(c=>c.id),vm.queue?.capacity]);}
function shell(){app.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-nav="home" aria-label="返回家园">${image('bears','idleFront')}<span>蜜林</span></button><div class="top-actions"><button class="calendar" data-command="calendar" aria-label="打开林间日历"></button><button class="icon-button" data-command="settings" aria-label="设置与存档">${icon('settings')}</button></div></header><div id="resource-bar"></div><div id="status"></div><main id="main-content" tabindex="-1"></main><nav class="bottom-nav" aria-label="主导航"></nav></div>`;}
function renderStatus(){const target=app?.querySelector('#status');if(!target)return;const text=storageIssue|| (loadBlocked?'这个存档目前无法读取。原始存档已保留，请先备份。':settlementFailed?(settlementFailureKind==='offline'?'离线结算':'时间推进')+'中断，已停止推进。原有进度已保留，请查看原因并备份。':readOnly?'另一页正在照料森林，本页暂时只读。':vm.settings?.paused?'森林已暂停，伙伴们在树荫下歇息。':'');const command=storageIssue||loadBlocked||settlementFailed?'saves':readOnly?'takeover':'pause';const label=storageIssue||loadBlocked?'存档与备份':settlementFailed?'备份与恢复':readOnly?'在此页继续':'继续游戏';const html=text?`<div class="status-banner ${storageIssue||loadBlocked||settlementFailed?'error':''}" role="status"><p>${esc(text)}</p><button data-command="${command}">${label}</button></div>`:'';if(target.innerHTML!==html)target.innerHTML=html;}
function hud(){const preferred=ui.page==='build'?(vm.buildings.find(c=>c.id===ui.buildChoice)?.costs||[]).map(c=>c.id):ui.page==='research'?['science','wood']:['honey','wood'];const list=[...new Set([...preferred,'honey','wood','science','minerals'])].map(id=>getResource(vm,id)).filter(r=>r.visible||['honey','wood'].includes(r.id)).slice(0,3);const key=list.map(r=>r.id).join();if(key!==ui.hudKey){app.querySelector('#resource-bar').innerHTML=`<div class="resource-ribbon">${list.map(r=>`<button class="resource-tile" data-command="resources" data-resource="${r.id}" aria-label="${esc(r.name)}库存">${image('resources',r.id)}<span><strong data-value="${r.id}"></strong><small data-rate="${r.id}"></small></span></button>`).join('')}<button class="icon-button all-resources" data-command="resources" aria-label="查看全部库存">${icon('box')}</button></div>`;ui.hudKey=key;}for(const r of list){writeText(`[data-value="${r.id}"]`,fmt(r.value,1));const rate=app.querySelector(`[data-rate="${r.id}"]`);if(rate){rate.textContent=rates(r);rate.classList.toggle('negative',r.rate<0&&!stopped());}const tile=app.querySelector(`[data-resource="${r.id}"]`);if(tile){tile.classList.toggle('at-cap',r.max!=null&&r.value>=r.max);tile.setAttribute('aria-label',`${r.name} ${fmt(r.value,1)}，${rates(r)}`);}}writeText('.calendar',`第 ${fmt(vm.calendar?.year||0)} 年 · ${vm.calendar?.seasonName||'春'}`);}
function nav(){const list=[['home','家园','buildings','hut'],['build','建造','buildings','hive'],['more','更多']];const key=list.map(x=>x[0]).join()+ui.page;if(key===ui.navKey)return;app.querySelector('.bottom-nav').innerHTML=list.map(([id,label,kind,item])=>`<button data-nav="${id}" class="${ui.page===id||ui.page==='queue'&&id==='build'||ui.page==='map'&&id==='home'||['research','village','crafts'].includes(ui.page)&&id==='more'?'active':''}" ${ui.page===id||ui.page==='queue'&&id==='build'||ui.page==='map'&&id==='home'||['research','village','crafts'].includes(ui.page)&&id==='more'?'aria-current="page"':''}>${kind?image(kind,item):`<span class="nav-more">${icon('more')}</span>`}<span>${label}</span></button>`).join('');ui.navKey=key;}
function heading(title,extra='',attributes=''){return `<header class="page-heading"><h1${attributes?" "+attributes:''}>${esc(title)}</h1>${extra}</header>`;}
function empty(text){return `<div class="empty-state">${image('bears','idleFront')}<p>${esc(text)}</p></div>`;}
