function updateGuide(){const guide=app.querySelector('#guide');if(!guide)return;const honey=getResource(vm,'honey');let target=vm.buildings.find(c=>c.id==='hive'),title='给森林添一个蜂箱',text='蜂箱会自己积攒蜂蜜。',page='build';if(honey.rate<0&&vm.bears.value){title='给伙伴留一些口粮';text='蜂蜜正在减少，安排采蜜熊或多建蜂箱。';page='village';}else if(!vm.buildings.find(c=>c.id==='hive')?.owned){title='给森林添一个蜂箱';text='采集 10 份蜂蜜，蜂箱就能自己积攒蜂蜜。';}else if(!vm.buildings.find(c=>c.id==='hut')?.owned){target=vm.buildings.find(c=>c.id==='hut');title='给第一位伙伴留一间小屋';text='采集蜂蜜，采木，然后建好小屋。';}else if(vm.bears.free){title=`${vm.bears.free} 只伙伴在等你安排`;text='去小熊页，选一份喜欢的工作。';page='village';}else if(!vm.buildings.find(c=>c.id==='library')?.owned){target=vm.buildings.find(c=>c.id==='library');title='给森林添一间书屋';text='书屋能装下更多新知识。';}else{const research=vm.science.find(c=>known(c)&&!c.completed);title=research?'林间有了新的发现':'慢慢照料，也是一种进步';text=research?`可以看看「${research.name}」需要什么。`:'点建筑看看详情，点小熊听听它的话。';page=research?'research':'build';}const complete=chapterComplete(vm);if(complete){target=null;title='第一章 · 家园长成了';text='伙伴们继续在这里生活。点开看看这份收获。';}const html=(target?buildingImage(target):image('bears','wave'))+`<span><b>${esc(title)}</b><small>${esc(text)}</small></span>`;if(guide.innerHTML!==html)guide.innerHTML=html;if(complete){guide.dataset.command='completion';delete guide.dataset.nav;}else{guide.dataset.nav=page;delete guide.dataset.command;}if(!complete&&page==='build'&&target)guide.dataset.buildTarget=target.id;else delete guide.dataset.buildTarget;const refine=vm.actions?.find(c=>c.type==='refine')||vm.crafts.find(c=>c.id==='wood');writeText('#refine-cost',(refine?.costs||[]).map(c=>`${fmt(c.value)} ${c.name}`).join(' + '));const observe=vm.actions?.find(c=>c.type==='observe'&&c.unlocked);const observeSlot=app.querySelector('#observe-slot');if(observeSlot){const markup=observe?`<button class="secondary" data-act="observe" data-id="${observe.id}">记录林间的发现</button>`:'';if(observeSlot.innerHTML!==markup)observeSlot.innerHTML=markup;}}
function buildPage(){const queueEntry=`<button class="queue-entry" data-nav="build/queue" aria-label="打开建造队列"><span>建造队列</span><b data-queue-count>${fmt(vm.queue?.used||0)}/${fmt(vm.queue?.capacity||3)}</b>${icon('arrow')}</button>`;const cards=vm.buildings.filter(known);const c=cards.find(c=>c.id===ui.buildChoice)||cards[0];if(!c)return heading('建造',queueEntry)+empty('先去林间收集一点蜂蜜吧。');ui.buildChoice=c.id;return heading('建造',queueEntry)+`<section class="build-station"><button class="build-showcase" data-detail="buildings:${c.id}" aria-label="查看${esc(c.name)}详情">${buildingImage(c)}</button><div class="build-caption"><h2>${esc(c.name)}</h2><span class="owned">已建 <b data-owned="${c.id}">${fmt(c.owned)}</b> 座</span><p>${esc(Array.isArray(c.effects)?c.effects.join(' · '):c.effects||c.description)}</p></div>${costs(c,'buildings')}${actionButtons(c,'buildings')}</section><div class="building-picker" aria-label="选择建筑">${cards.map(b=>`<button class="building-option ${b.id===c.id?'selected':''}" data-build-choice="${b.id}" aria-pressed="${b.id===c.id}">${buildingImage(b)}<b>${esc(b.name)}</b>${b.owned?`<small>×${fmt(b.owned)}</small>`:''}</button>`).join('')}</div>${c.owned?`<details class="fold"><summary>管理这处建筑</summary><div class="fold-content"><p class="detail-note">${c.toggleable?'可以暂停生产，停止消耗原料。':'建筑会持续为家园带来帮助。'}</p><div class="action-row">${c.toggleable?`<button class="secondary" data-act="toggle" data-id="${c.id}">${c.enabled?'暂停生产':'恢复生产'}</button>`:''}<button class="danger" data-act="sell" data-id="${c.id}">拆除 1 座</button></div></div></details>`:''}`;}
function queueSection(c){return ({build:'buildings',research:'science',upgrade:'workshop'})[c.targetType||c.type];}
function queuePicture(c){const section=queueSection(c),card=vm[section]?.find(b=>b.id===(c.targetId||c.id))||c;return artFor(card,section);}
function queueCosts(c,kind,id){return `<div class="decision-costs" data-queue-costs="${kind}:${esc(id)}">${costMarkup(c)}</div>`;}
function queuePage(){
 const q=vm.queue||{items:[],options:[],used:0,capacity:3},pages=Math.max(1,Math.ceil(q.items.length/25));ui.queuePage=Math.min(Math.max(0,ui.queuePage),pages-1);const start=ui.queuePage*25;
 return heading('建造队列',`<button class="queue-back" data-nav="build" aria-label="返回建造">‹ 返回建造</button>`,'tabindex="-1" data-queue-heading')+`<section class="queue-panel"><div class="queue-overview"><b>按顺序完成</b><span><b data-queue-count>${fmt(q.used)}/${fmt(q.capacity)}</b> 已排队</span></div><p class="queue-rule" data-queue-rule>${q.paused?'已随游戏暂停':'物资齐备后自动完成 · 队首优先'}</p><ol class="queue-list">${q.items.slice(start,start+25).map((c,offset)=>`<li class="queue-item"><div class="queue-item-heading"><span class="queue-number">${start+offset+1}</span><span class="queue-picture">${queuePicture(c)}</span><h2>${esc(c.name)} <small>×${fmt(c.amount)}</small></h2></div><p class="queue-status" data-queue-status="${c.index??(start+offset)}">${esc(c.reason||c.status||'等待执行')}</p>${queueCosts(c,'item',c.index??(start+offset))}<div class="queue-controls"><button class="secondary" data-act="queueUp" data-id="${c.index??(start+offset)}" aria-label="上移${esc(c.name)}" ${start+offset===0?'disabled':''}>↑</button><button class="secondary" data-act="queueDown" data-id="${c.index??(start+offset)}" aria-label="下移${esc(c.name)}" ${start+offset===q.items.length-1?'disabled':''}>↓</button><button class="secondary" data-act="queueRemove" data-id="${c.index??(start+offset)}" aria-label="移除一项${esc(c.name)}">移除 1 项</button>${c.amount>1?`<button class="text-button" data-act="queueRemove" data-id="${c.index??(start+offset)}" data-amount="max" aria-label="移除整组${esc(c.name)}">移除整组</button>`:''}</div></li>`).join('')||`<li class="queue-empty">${image('buildings','hive')}<span>把想建的放进来<small>在下方排队，现在不扣物资</small></span></li>`}</ol>${pages>1?`<div class="queue-pagination" aria-label="队列翻页"><button class="secondary" data-queue-page="${ui.queuePage-1}" ${ui.queuePage===0?'disabled':''}>前 25 项</button><span>${ui.queuePage+1} / ${pages}</span><button class="secondary" data-queue-page="${ui.queuePage+1}" ${ui.queuePage===pages-1?'disabled':''}>后 25 项</button></div>`:''}${q.items.length?'<button class="queue-clear danger" data-act="queueClear" data-id="confirm">清空队列</button>':''}<h2 class="queue-choices-heading">添加到队列</h2><div class="queue-choices">${q.options.filter(c=>c.unlocked&&!c.completed).map(c=>`<article class="queue-choice"><span class="queue-picture">${queuePicture(c)}</span><h3>${esc(c.name)}</h3><button class="secondary" data-act="queueEnqueue" data-id="${esc(c.id)}" aria-label="将${esc(c.name)}加入队列" aria-disabled="${!c.available||!canAct()}">排队 ＋</button>${queueCosts(c,'option',c.id)}</article>`).join('')}</div></section>`;
}
function researchPage(){const sections=[['science','研究'],['workshop','技艺']].filter(([s])=>vm[s]?.some(known));if(!sections.some(([s])=>s===ui.researchTab))ui.researchTab=sections[0]?.[0]||'science';const section=ui.researchTab,cards=(vm[section]||[]).filter(known),fresh=cards.filter(c=>!c.completed),done=cards.filter(c=>c.completed);return heading('研究')+(sections.length>1?`<div class="segmented">${sections.map(([s,label])=>`<button data-research-tab="${s}" class="${s===section?'selected':''}" aria-pressed="${s===section}">${label}</button>`).join('')}</div>`:'')+`<div class="notebook-intro"><span>蜜林研究手册</span><small>点插画查看详情</small></div><div class="research-list">${fresh.map(c=>card(c,section)).join('')}</div>`+(!fresh.length?empty('已经读完这一页，继续照料家园吧。'):'')+(done.length?`<details class="fold"><summary>已经掌握 · ${done.length}</summary><div class="research-list">${done.map(c=>card(c,section)).join('')}</div></details>`:'');}
function villagePage(){return heading('小熊')+`<div class="village-overview">${image('bears','wave')}<div><h2>${fmt(vm.bears.value)} 只伙伴</h2><p>空闲 ${fmt(vm.bears.free)} · 住房 ${fmt(vm.bears.max)}</p><small>幸福感 ${fmt(vm.bears.happiness)}% · 每只伙伴都需要蜂蜜</small></div></div>`+(!vm.bears.value?empty('小屋已经准备好，留足蜂蜜，伙伴会慢慢搬进来。'):'')+`<div class="job-list">${vm.jobs.filter(known).map(c=>`<article class="job-card"><button class="job-portrait" data-detail="jobs:${c.id}" aria-label="${esc(c.name)}工作详情">${image('workers',c.id,'','ready')}</button><div><h2>${esc(c.name)}</h2><p>${esc(c.description||c.effects)}</p></div><div class="job-stepper"><button data-act="unassign" data-id="${c.id}" aria-label="减少一只${esc(c.name)}">−</button><b data-assigned="${c.id}">${fmt(c.assigned)}</b><button data-act="assign" data-id="${c.id}" aria-label="增加一只${esc(c.name)}">＋</button><button class="text-button" data-act="assign" data-id="${c.id}" data-amount="max">分配空闲伙伴</button></div></article>`).join('')}</div>`+(vm.actions.some(c=>c.type==='hunt'&&c.unlocked)?`<div class="page-body"><h2>去林间走走</h2><p class="detail-note">消耗 100 活力，寻找毛皮和象牙。</p><div class="action-row"><button class="primary" data-act="hunt" data-id="hunt">巡林 1 次</button><button class="secondary" data-act="hunt" data-id="hunt" data-amount="max">批量巡林</button></div></div>`:'');}
function craftsPage(){return heading('林间工坊',`<button data-nav="more">返回更多</button>`)+`<div class="craft-list">${vm.crafts.filter(known).map(c=>card(c,'crafts')).join('')}</div>`;}
function morePage(){const craft=vm.crafts.some(c=>c.id!=='wood'&&known(c));return heading('更多')+`<div class="more-list">${vm.science.some(known)?`<button data-nav="research">${image('resources','science')}<span>林间研究</span>${icon('arrow')}</button>`:''}${vm.bears.max>0||vm.bears.value>0?`<button data-nav="village">${image('bears','wave')}<span>小熊与工作</span>${icon('arrow')}</button>`:''}${craft?`<button data-nav="crafts">${image('buildings','workshop')}<span>林间工坊</span>${icon('arrow')}</button>`:''}<button data-command="journal">${icon('leaf')}<span>林间手记</span>${icon('arrow')}</button><button data-command="settings">${icon('settings')}<span>设置</span>${icon('arrow')}</button><button data-command="saves">${icon('save')}<span>存档与备份</span>${icon('arrow')}</button><button data-command="help">${icon('help')}<span>游戏说明</span>${icon('arrow')}</button></div><p class="save-foot">第一章 · 林间家园<br><span id="save-label">进度保存在此设备</span></p>`;}
function mapPage(){return heading('森林地图',`<button data-nav="home">回到家园</button>`)+`<div class="world-map-scroll" tabindex="0" aria-label="可上下滚动的森林地图">${visibleRegions(vm).map(r=>{const {buildings,height}=sceneLayout(vm,r.id),previewHeight=Math.min(320,height*.36),scale=previewHeight/height;return `<button class="map-region" data-region="${r.id}" aria-label="进入${r.name}，${buildings.length}类建筑" style="background-image:url('${esc(art.scenery?.background||art.background)}')"><span class="region-buildings" style="height:${previewHeight}px" aria-hidden="true">${buildings.map(({card:c,x,y})=>`<span class="map-building" data-map-building="${c.id}" style="--x:${x}%;--y:${y/height*100}%;height:${176*scale}px">${buildingImage(c)}</span>`).join('')}</span><b>${r.name}</b><small>${buildings.length?'已有 '+buildings.length+' 类建筑':'一片安静的林间空地'}</small></button>`;}).join('')}</div>`;}

function updateViewLayout(){const shell=app?.querySelector('.app-shell');shell?.classList.toggle('home-view',ui.page==='home');shell?.classList.toggle('map-view',ui.page==='map');}
function render(force=false){if(!game||!app)return;vm=game.snapshot();updateViewLayout();if(ui.page==='home')normalizeHomeRegion();renderStatus();hud();nav();const key=pageKey(),structure=structuralKey(),main=app.querySelector('#main-content');if(force||ui.pageKey!==key||ui.page!=='home'&&ui.structureKey!==structure){const focus=activeKey();const pageScroll=main.scrollTop,windowScroll=window.scrollY;const picker=main.querySelector('.building-picker')?.scrollLeft||0;const open=[...main.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);if(ui.page==='home'&&main.querySelector('.world-board')&&ui.pageKey?.startsWith('home:')){ui.scrolls[ui.pageKey]=main.querySelector('.world-scene').scrollTop;}main.innerHTML=({home,build:buildPage,research:researchPage,village:villagePage,more:morePage,map:mapPage,crafts:craftsPage,queue:queuePage}[ui.page]||home)();if(ui.page==='home')main.querySelector('.world-scene').scrollTop=ui.scrolls[pageKey()]||0;for(const d of main.querySelectorAll('details'))if(open.includes(d.querySelector('summary')?.textContent))d.open=true;if(main.querySelector('.building-picker'))main.querySelector('.building-picker').scrollLeft=picker;main.scrollTop=pageScroll;if(ui.pageKey===key)window.scrollTo({top:windowScroll,behavior:'instant'});restoreFocus(focus);ui.pageKey=pageKey();}ui.structureKey=structure;if(ui.page==='home')updateScene();updateLive();ui.queueKey=queueOrderKey(vm);}
function findCard(type,id,section){if(type==='queueEnqueue')return vm.queue?.options?.find(c=>c.id===id);if(['queueUp','queueDown','queueRemove'].includes(type))return vm.queue?.items?.find(c=>String(c.index)===String(id));if(type==='queueClear')return vm.queue;if(section&&vm[section])return vm[section].find(c=>c.id===id);if(['build','sell','toggle'].includes(type))return vm.buildings.find(c=>c.id===id);if(['assign','unassign'].includes(type))return vm.jobs.find(c=>c.id===id);if(type==='research')return vm.science.find(c=>c.id===id);if(type==='upgrade')return vm.workshop.find(c=>c.id===id);return vm.actions.find(c=>c.id===id&&c.type===type)||vm.crafts.find(c=>c.id===id);}
function allowed(type,c){if(!canAct())return false;if(type==='queueClear')return !!c?.items?.length;if(type==='queueRemove')return c?.amount>0;if(type==='queueUp')return c?.index>0;if(type==='queueDown')return c?.index<((vm.queue?.items?.length||0)-1);if(type==='sell')return c?.owned>0;if(type==='toggle')return c?.owned>0&&c.toggleable;if(type==='unassign')return c?.assigned>0;return c?.available===true;}
function updateLive(){for(const el of document.querySelectorAll('[data-queue-count]'))el.textContent=`${fmt(vm.queue?.used||0)}/${fmt(vm.queue?.capacity||3)}`;writeText('[data-queue-rule]',vm.queue?.paused?'已随游戏暂停':'物资齐备后自动完成 · 队首优先');for(const el of document.querySelectorAll('[data-queue-costs]')){const [kind,...parts]=el.dataset.queueCosts.split(':'),id=parts.join(':'),c=kind==='item'?vm.queue?.items?.find(c=>String(c.index)===id):vm.queue?.options?.find(c=>c.id===id);if(c){const html=costMarkup(c);if(el.innerHTML!==html)el.innerHTML=html;}}for(const el of document.querySelectorAll('[data-queue-status]')){const c=vm.queue?.items?.find(c=>String(c.index)===el.dataset.queueStatus);if(c)el.textContent=c.reason||c.status||'等待执行';}for(const el of document.querySelectorAll('[data-costs]')){const [section,id]=el.dataset.costs.split(':');const c=vm[section]?.find(c=>c.id===id);if(c){const html=costMarkup(c);if(el.innerHTML!==html)el.innerHTML=html;}}for(const el of document.querySelectorAll('[data-act]')){const c=findCard(el.dataset.act,el.dataset.id,el.dataset.section);const yes=allowed(el.dataset.act,c);el.setAttribute('aria-disabled',String(!yes));}for(const c of vm.jobs||[])for(const el of document.querySelectorAll(`[data-assigned="${c.id}"]`))el.textContent=fmt(c.assigned);writeText('#save-label',storageIssue||loadBlocked?'存档需要检查':vm.saveStatus?.at?'刚刚已保存':'进度保存在此设备');if(dialog?.kind==='resources')updateInventory();}
function rememberScene(){const scene=app.querySelector('.world-scene');if(scene)ui.scrolls[pageKey()]=scene.scrollTop;}
function normalizeHomeRegion(){
 if(!visibleRegions(vm).some(r=>r.id===ui.region))ui.region='village';
 const [page,region]=location.hash.slice(1).split('/');
 if(page==='home'&&region&&region!=='map'&&region!==ui.region)history.replaceState(history.state,'','#home/'+ui.region);
}
function readHash(){const [page,region]=location.hash.slice(1).split('/');ui.page=['home','build','research','village','more','map','crafts'].includes(page)?page:'home';if(ui.page==='build'&&region==='queue')ui.page='queue';if(ui.page==='home'&&region==='map')ui.page='map';else if(ui.page==='home'){ui.region=region||ui.region;normalizeHomeRegion();}if(ui.page==='crafts'&&!vm.crafts.some(c=>c.id!=='wood'&&known(c)))ui.page='more';if(ui.page==='research'&&!vm.science.some(known))ui.page='home';}
function navigate(page,region){rememberScene();if(page==='home'&&!region&&ui.revealBuilding)region=visibleRegions(vm).find(r=>r.buildings.includes(ui.revealBuilding))?.id;const hadDialogHistory=dialogHistory;closeDialog(true);const hash=page==='home'?'home/'+(region||ui.region):page;if(hadDialogHistory){const state={...history.state};delete state.forestDialog;history.replaceState(state,'','#'+hash);readHash();render(true);window.scrollTo({top:0,behavior:'instant'});return;}if(location.hash==='#'+hash){readHash();render(true);}else location.hash=hash;}
function dialogBody(){if(!dialog)return '';const c=dialog.section?vm[dialog.section]?.find(c=>c.id===dialog.id):null;switch(dialog.kind){case 'detail':if(!c||!known(c))return '<p>这个发现还没有出现在森林里。</p>';return `<div class="detail-hero">${dialog.section==='jobs'?image('workers',c.id):artFor(c,dialog.section)}</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p>${c.effects?`<div class="detail-effect">${esc(Array.isArray(c.effects)?c.effects.join(' · '):c.effects)}</div>`:''}${dialog.section==='jobs'?`<p>已分配 ${fmt(c.assigned)} 只伙伴</p><button class="primary" data-nav="village">安排工作</button>`:costs(c,dialog.section)+actionButtons(c,dialog.section)}${['buildings','crafts'].includes(dialog.section)&&!c.completed?`<div class="action-row">${action(c,dialog.section,'尽可能'+(dialog.section==='buildings'?'建造':'制作'),'max','secondary')}</div><p class="detail-note">批量操作前会再次确认，可能用完所需原料。</p>`:''}${dialog.section==='buildings'&&c.owned?`<div class="action-row">${c.toggleable?`<button class="secondary" data-act="toggle" data-id="${c.id}">${c.enabled?'暂停生产':'恢复生产'}</button>`:''}<button class="danger" data-act="sell" data-id="${c.id}">拆除 1 座</button></div>`:''}`;
 case 'bear':{const b=vm.bears.individuals.find(b=>String(b.id)===dialog.id);if(!b)return '<p>伙伴正在林间走动。</p>';return `<div class="detail-hero">${image('workers',b.job||'idle')||image('bears','idleFront')}</div><h2>${esc(b.name||'小熊')}</h2><p>${esc(stopped()?'我在这里，等你准备好再继续。':bearLines[b.job]||bearLines.idle)}</p><button class="primary" data-nav="village">看看伙伴的工作</button>`;}
 case 'resources':return `<div id="inventory">${vm.resources.filter(r=>r.visible).map(r=>`<div class="inventory-item" data-inventory="${r.id}">${image('resources',r.id)}<div><b>${esc(r.name)}</b><p>${esc(r.description||'')}</p></div><div class="inventory-number"><b data-stock="${r.id}">${fmt(r.value,1)}</b><small>${r.max==null?'不限容量':'容量 '+fmt(r.max)}</small><small data-stock-rate="${r.id}">${rates(r)}</small></div></div>`).join('')}</div>`;
 case 'settings':return `<button class="setting-row" data-command="pause"><span><b>暂停游戏</b><small>暂停期间，生产和日历都停下来。</small></span><span class="setting-value">${vm.settings.paused?'已暂停':'生长中'}</span></button><button class="setting-row" data-command="offline"><span><b>离线生长</b><small>关闭页面后继续计算，最多结算 ${fmt(constants.MAX_OFFLINE_SECONDS/3600,2)} 小时。小熊仍会消耗蜂蜜。</small></span><span class="setting-value">${vm.settings.offline?'已开启':'已关闭'}</span></button><button class="setting-row" data-command="motion"><span><b>减少动态效果</b><small>让工作姿势和加载小熊保持安静。</small></span><span class="setting-value">${settings.reducedMotion?'已开启':'已关闭'}</span></button><div class="save-actions"><button class="secondary" data-command="saves">存档与备份</button></div>`;
 case 'saves':return `<p>进度只保存在当前浏览器。换设备前，先导出一份存档。</p>${storageIssue||loadBlocked?`<p class="negative">${esc(storageIssue||vm.saveStatus?.message||'存档无法读取，原始数据已保留。')}</p>`:''}${settlementFailed?`<p class="negative">${esc(settlementFailureMessage)}</p><p>当前推进已停止，已保存的原始存档不会被覆盖。请先下载备份，再重新加载重试；不会跳过尚未结算的时间。</p>`:''}<div class="save-actions">${!settlementFailed?'<button class="primary" data-command="save">保存当前进度</button>':''}${!loadBlocked&&!vm.pendingOffline?'<button class="secondary" data-command="export">导出当前存档</button>':''}${readStorage(constants.SAVE_KEY)!==null?'<button class="secondary" data-command="backup-slot">下载已保存的原始存档</button>':''}${readStorage(LEGACY_KEY)!==null?'<button class="secondary" data-command="legacy">下载旧存档原始备份</button>':''}${settlementFailed?'<button class="primary" data-command="reload">重新加载</button>':''}<button class="secondary" data-command="import">导入存档文件</button></div><p class="detail-note">导入前会检查存档兼容性，再由你确认替换。旧存档使用独立位置，本章不会改写它。</p>`;
 case 'help':return `<div class="help-content">${image('bears','wave')}<h2>一点点，长成家园</h2><h3>从蜂蜜和木头开始</h3><p>在家园采集蜂蜜，再用蜂蜜采木。蜂箱会持续生产蜂蜜；小屋建好后，伙伴会陆续搬进来。</p><h3>让每只小熊都有一份工作</h3><p>在小熊页分配采蜜、伐木和研究等工作。顶部显示净产量，已经扣除了伙伴的口粮与生产消耗。冬天蜂蜜较少，提前留粮。</p><h3>读书，也动手</h3><p>书屋扩大知识容量，研究带来新的建筑。工坊开放木梁和石板制作，技艺能让日常工作更顺利。</p><h3>先排队，慢慢建</h3><p>建造页右上角可以打开建造队列。把已经发现的建筑、研究或技艺排好顺序，物资齐备后就会自动完成。队首优先，暂停游戏时队列也会暂停。</p><h3>地图和建筑</h3><p>家园地图可以上下滑动。地图与家园使用同一组区域；点建筑看成本、效果和管理选项，点小熊听一句林间闲话。</p><h3>第一章的心愿</h3><p>掌握营造技术，建好木屋、仓库和伐木场，林间家园就长成了。完成后仍能继续游玩。</p><h3>把家园收好</h3><p>游戏自动保存。更多中可以暂停、管理离线生长、导出备份。批量制作和拆除都会先询问你。</p></div>`;
 case 'completion':return `<div class="detail-hero">${image('bears','wave')}</div><h2>林间家园长成了</h2><p>营造技术读懂了，木屋、仓库和伐木场，也都有了自己的位置。</p><p>这是一段慢慢积攒的林间时光。和小熊一起，继续照料这片森林吧。</p><button class="primary" data-command="close">继续照料家园</button>`;
 case 'calendar':return `<h2>第 ${fmt(vm.calendar.year)} 年 · ${esc(vm.calendar.seasonName)} ${fmt(vm.calendar.day)} 天</h2><p>${esc(vm.calendar.weatherName||'天气平和')}。季节和天气都会影响蜂蜜产量。</p><p>给冬天留一点余粮：安排采蜜熊，添置蜂箱和储存建筑，让伙伴们安心过冬。</p>`;
 case 'journal':return vm.log.map(l=>`<p>${esc(l.text)}</p>`).join('')||'<p>森林的故事，才刚刚开始。</p>';
 case 'confirm':return `<h2>${esc(dialog.heading)}</h2><p class="confirm-copy">${esc(dialog.text)}</p><div class="action-row"><button class="secondary" data-command="cancel">先不操作</button><button class="${dialog.destructive?'danger':'primary'}" data-command="confirm">确认继续</button></div>`;
 case 'offline':return `<div class="offline-body">${image('bears','idleFront')}<h2>欢迎回到蜜林</h2><p>离开了 ${fmt((vm.offlineReport?.seconds||0)/60,1)} 分钟，森林还记得你。</p></div>${Object.entries(vm.offlineReport?.resources||{}).filter(([,v])=>Math.abs(v)>.01).map(([id,v])=>`<p>${esc(getResource(vm,id).name)} <b class="${v<0?'negative':''}">${signed(v)}</b></p>`).join('')||'<p>这段时间没有明显的物资变化。</p>'}<button class="primary" data-command="close">继续照料森林</button>`;
 case 'settling':return `<div class="offline-body">${image('bears','idleFront')}<h2>正在整理林间收获</h2><p>按实际规则计算离开的时间。请稍候，完成后就能继续。</p><progress class="offline-progress" value="0" max="1" aria-label="离线结算进度"></progress><span id="offline-label">0%</span></div>`;
 default:return '';}}
function openDialog(kind,title,data={}){if(settling&&kind!=='settling')return;if(!dialog){returnFocus=document.activeElement;if(kind!=='settling'&&kind!=='offline'){history.pushState({...history.state,forestDialog:true},'');dialogHistory=true;}}if(kind==='confirm'&&dialog&&dialog.kind!=='confirm')parentDialog={...dialog};else if(kind!=='confirm')parentDialog=null;dialog={kind,title,...data};refreshDialog(true);}
function refreshDialog(focus=false){if(!dialog)return;const oldScroll=dialogRoot.querySelector('.dialog-body')?.scrollTop||0;const focusKey=activeKey();dialogRoot.innerHTML=`<div class="dialog-backdrop"><section class="dialog" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(dialog.title)}</h2>${dialog.kind==='settling'?'':`<button class="icon-button" data-command="close" aria-label="关闭弹窗">${icon('close')}</button>`}</header><div class="dialog-body">${dialogBody()}</div></section></div>`;app.inert=true;document.body.classList.add('modal-open');dialogRoot.querySelector('.dialog-body').scrollTop=oldScroll;updateLive();if(focus)(dialogRoot.querySelector('[data-command="close"]')||dialogRoot.querySelector('.dialog')).focus({preventScroll:true});else restoreFocus(focusKey);}
function closeDialog(fromHistory=false){if(!dialog||settling)return;const back=dialogHistory&&!fromHistory;dialog=null;parentDialog=null;dialogHistory=false;dialogRoot.innerHTML='';app.inert=false;document.body.classList.remove('modal-open');returnFocus?.isConnected?returnFocus.focus({preventScroll:true}):app.querySelector('#main-content')?.focus({preventScroll:true});returnFocus=null;if(back)history.back();}
function cancelDialog(){if(parentDialog){dialog=parentDialog;parentDialog=null;refreshDialog(true);}else closeDialog();}
function confirmAction(heading,text,confirm,destructive=false){openDialog('confirm','请确认',{heading,text,confirm,destructive});}
function updateInventory(){for(const r of vm.resources){writeText(`[data-stock="${r.id}"]`,fmt(r.value,1),dialogRoot);writeText(`[data-stock-rate="${r.id}"]`,rates(r),dialogRoot);}}
function perform(type,id,amount=1){if(!canAct()){notify(storageIssue||loadBlocked?'请先检查并备份存档。':readOnly?'另一页正在照料森林，请先选择在此页继续。':'请等当前结算完成。');return {ok:false};}const result=game.act(type,id,amount);vm=game.snapshot();if(result.ok!==false){if(type==='build')ui.revealBuilding=id;save();render();if(dialog?.kind==='detail')refreshDialog();if(type!=='gather'&&type!=='refine'||amount!==1)notify(result.message||'已经完成。');else if(type==='refine')notify(result.message||'木头已经收好了。',1600);}else notify(result.message||'还需要准备一点物资。');return result;}
function requestAction(button){const {act:type,id,section}=button.dataset,amount=button.dataset.amount==='max'?'max':Math.max(1,Number(button.dataset.amount)||1);const c=findCard(type,id,section);if(!allowed(type,c)){notify(!canAct()?'当前暂停操作，请查看顶部提示。':c?.reason||'还需要准备一点物资。');return;}if(type==='queueClear'){confirmAction('清空建造队列？','移除所有尚未完成的排队项目。已经完成的建筑与研究会保留。',()=>{closeDialog();perform('queueClear','confirm');},true);return;}if(type==='queueRemove'){perform(type,id,amount);return;}if(type==='sell'){confirmAction(`拆除一座${c.name}？`,'这会失去这座建筑的作用，并返还部分物资。住房减少可能影响伙伴，仓库减少可能损失超出容量的物资。此操作无法撤销。',()=>{closeDialog();perform(type,id,1);},true);return;}if((amount==='max'||amount>1)&&!['assign','unassign'].includes(type)){const estimate=batchSummary(c,amount),unit=(c.costs||[]).map(x=>`${fmt(x.value,2)} ${x.name}`).join('、');const text=type==='build'?`将尝试建造${amount==='max'?'尽可能多的':amount+' 座'}${c.name}。首座需要 ${unit}，后续价格会逐座增加，实际建造数量按库存计算，可能用完所需原料。`:`将尝试${type==='hunt'?'巡林':'制作'} ${fmt(estimate.count)} 次。按当前原料估算消耗 ${estimate.costs.map(x=>`${fmt(x.value,2)} ${x.name}`).join('、')}。实际数量按确认时库存计算，可能用完原料，超出容量的成品也可能损失。`;confirmAction('确认批量操作？',text,()=>{closeDialog();perform(type,id,amount);});return;}perform(type,id,amount);}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(key,name){const text=readStorage(key);if(text===null){notify('没有找到可下载的存档。');return;}download(text,name);notify('已准备原始存档下载，内容未作修改。');}
function exportSave(){if(loadBlocked){backup(constants.SAVE_KEY,'Beargame-存档原始备份.json');return;}try{download(game.exportSave(),`Beargame-林间存档-${new Date().toISOString().slice(0,10)}.json`);notify('已准备存档下载，请妥善保存。');}catch(e){notify('无法导出：'+e.message,6000);}}
function toggleSetting(key){if(!canAct()){notify('当前页面不能更改游戏节奏。');return;}flushActive();if(!canAct())return;game.setSetting(key,!game.snapshot().settings[key]);lastTick=now();save();render();refreshDialog();}
async function command(name){switch(name){case 'resources':openDialog('resources','森林仓库');break;case 'settings':openDialog('settings','照料森林的节奏');break;case 'saves':openDialog('saves','存档与备份');break;case 'help':openDialog('help','关于蜜林');break;case 'journal':openDialog('journal','林间手记');break;case 'calendar':openDialog('calendar','林间日历');break;case 'completion':openDialog('completion','第一章 · 家园长成了');break;case 'close':dialog?.kind==='confirm'?cancelDialog():closeDialog();break;case 'cancel':cancelDialog();break;case 'confirm':dialog?.confirm?.();break;case 'pause':toggleSetting('paused');break;case 'offline':toggleSetting('offline');break;case 'motion':settings.reducedMotion=!settings.reducedMotion;writeStorage(UI_KEY,JSON.stringify(settings));document.documentElement.classList.toggle('motion-reduced',settings.reducedMotion);renderStatus();refreshDialog();break;case 'save':{const r=save();notify(r.message||(r.ok?'森林已经好好保存。':'保存失败，请导出备份。'));render();break;}case 'export':exportSave();break;case 'legacy':backup(LEGACY_KEY,'Beargame-旧存档原始备份.json');break;case 'backup-slot':backup(constants.SAVE_KEY,'Beargame-存档原始备份.json');break;case 'import':if(readOnly||settling){notify('请先在此页继续游戏。');break;}document.querySelector('#save-file').click();break;case 'reload':location.reload();break;case 'takeover':confirmAction('在此页继续照料森林？','另一页会停止推进。本页将重新读取最近保存的进度。',()=>{closeDialog();storageIssue='';if(!claim(true)){renderStatus();notify('没有取得保存权限，请检查浏览器存储设置。');return;}reloadGame();ui.structureKey='';render(true);settlePending();});break;}}
async function importFile(event){if(event.target.id!=='save-file')return;const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>MAX_SAVE_BYTES){notify('文件过大，请选择游戏导出的 JSON 存档。');return;}try{const text=await file.text();parseSave(text);confirmAction('替换当前森林？',`将导入「${file.name}」。当前本章进度会被替换，建议先导出备份。`,()=>{if(readOnly||!ownsLease()||storageIssue||settling){notify('当前无法导入，请检查保存权限。');return;}const result=game.importSave(text);if(result.ok===false){notify(result.message||'无法导入，原存档保持不变。',6000);return;}loadBlocked=false;settlementFailed=false;settlementFailureKind='';settlementFailureMessage='';ui.revealBuilding=null;closeDialog();lastTick=now();save();ui.structureKey='';render(true);notify(storageIssue?'已读入本页，但保存失败，请立即导出备份。':'存档已导入，欢迎回来。');settlePending();},true);}catch(e){notify('无法导入：'+e.message+'。当前存档未改变。',7000);}}
function onClick(event){const b=event.target.closest('button');if(!b){if(event.target.classList?.contains('dialog-backdrop')&&!settling)cancelDialog();return;}if(b.disabled||settling)return;if(b.dataset.nav){if(b.dataset.buildTarget)ui.buildChoice=b.dataset.buildTarget;navigate(b.dataset.nav);return;}if(b.dataset.region){navigate('home',b.dataset.region);return;}if(b.dataset.queuePage!==undefined){ui.queuePage=Math.max(0,Number(b.dataset.queuePage)||0);render();return;}if(b.dataset.buildChoice){ui.buildChoice=b.dataset.buildChoice;render();return;}if(b.dataset.researchTab){ui.researchTab=b.dataset.researchTab;render();return;}if(b.dataset.detail){const [section,id]=b.dataset.detail.split(':');openDialog('detail','林间图鉴',{section,id});return;}if(b.dataset.bear){openDialog('bear','林间聊聊',{id:b.dataset.bear});return;}if(b.dataset.act){requestAction(b);return;}if(b.dataset.command)command(b.dataset.command);}
function onKey(event){if(!dialog)return;if(event.key==='Escape'){if(settling)return;event.preventDefault();cancelDialog();return;}if(event.key!=='Tab')return;const list=[...dialogRoot.querySelectorAll('button:not([disabled]),input:not([hidden]),summary')].filter(el=>el.offsetParent!==null),first=list[0],last=list.at(-1);if(!first){event.preventDefault();dialogRoot.querySelector('.dialog').focus();return;}if(event.shiftKey&&(document.activeElement===first||!dialogRoot.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialogRoot.contains(document.activeElement))){event.preventDefault();first.focus();}}
// Deferred offline time must settle before any live tick, including lifecycle flushes.
function flushActive(){const current=now(),seconds=Math.max(0,(current-lastTick)/1000);lastTick=current;if(!canAct()||hiddenAt!==null||seconds<=0)return;const pending=game.snapshot().pendingOffline;if(pending>0){settle(pending);return;}if(seconds>5){if(vm.settings.offline&&!vm.settings.paused){settle(seconds);return;}game.tick(vm.settings.paused?seconds:0);return;}const r=game.tick(seconds);if(r?.ok===false){stopProgress(r.message,'live');notify(settlementFailureMessage,6000);}}
async function settle(seconds){if(!canAct()||!(seconds>0)||!game.snapshot().settings.offline||game.snapshot().settings.paused)return;const interrupted=dialog?{dialog:{...dialog},parent:parentDialog,history:dialogHistory}:null;const finishDialog=()=>{if(interrupted&&(!interrupted.history||dialogHistory)){dialog=interrupted.dialog;parentDialog=interrupted.parent;refreshDialog();}else closeDialog(true);};settling=true;const target=game;openDialog('settling','整理离线收获');renderStatus();try{const result=await target.catchUpAsync(seconds,{onProgress:({progress})=>{const bar=dialogRoot.querySelector('.offline-progress');if(bar)bar.value=progress;writeText('#offline-label',Math.round(progress*100)+'%',dialogRoot);}});settling=false;lastTick=now();if(result.ok===false){stopProgress(result.message,'offline');finishDialog();notify(settlementFailureMessage,7000);render();return;}if(game!==target||!ownsLease()){readOnly=true;finishDialog();render();return;}vm=game.snapshot();save();finishDialog();render();if(document.hidden)hiddenAt=now();else if(result.seconds>30||seconds>30){if(interrupted)notify('离开的收获已经整理好了，原来的页面还在。');else openDialog('offline','离开时的森林');}}catch(error){settling=false;stopProgress('离线结算中断：'+(error?.message||String(error)),'offline');finishDialog();notify(settlementFailureMessage,7000);render();}}
function settlePending(){if(vm.pendingOffline>0&&!readOnly&&!storageIssue&&!loadBlocked)return settle(vm.pendingOffline);}
function step(){if(document.hidden||settling)return;if(!ownsLease()&&!readOnly){readOnly=true;render();}if(canAct())flushActive();else lastTick=now();if(!settling&&canAct()&&now()-lastSave>=15000)save();if(!settling)render();}
function onVisibility(){if(document.hidden){document.documentElement.classList.add('scene-paused');if(canAct()&&!settling&&hiddenAt===null){flushActive();if(!settling){save();hiddenAt=now();}}return;}document.documentElement.classList.remove('scene-paused');if(settling)return;if(!ownsLease()){readOnly=true;lastTick=now();render();return;}if(hiddenAt!==null&&!storageIssue&&!loadBlocked){hiddenAt=null;reloadGame();render();settlePending();}else{lastTick=now();render();}}
function onStorage(event){if(event.key===LEASE_KEY&&!ownsLease()){readOnly=true;lastTick=now();render();}if(event.key===constants.SAVE_KEY&&readOnly&&!settling){reloadGame();render();}}
async function preload(){
 let complete=0,failed=false;const progress=document.querySelector('#loading-progress');progress.max=forestAssets.length;
 try{await Promise.all(forestAssets.map(async src=>{
  await new Promise((resolve,reject)=>{const img=new Image();let ended=false;const done=error=>{if(ended)return;ended=true;clearTimeout(timer);img.onload=img.onerror=null;error?reject(error):resolve();};const timer=setTimeout(()=>done(Error('图片加载超时，请检查网络。')),45000);img.onload=async()=>{try{await img.decode?.();done();}catch{done(Error('图片暂时无法显示。'));}};img.onerror=()=>done(Error('图片加载失败，请检查网络。'));img.src=src;});
  if(failed)return;complete++;progress.value=complete;writeText('#loading-label',`正在准备家园 · ${Math.round(complete/forestAssets.length*100)}%`,document);
 }));}catch(error){failed=true;throw error;}
}
async function finishLoading(){
 const screen=document.querySelector('#loading-screen');
 if(screen&&!settings.reducedMotion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
  // Only the ready loader fades. The rendered home has no second opening scene.
  screen.getBoundingClientRect();
  await new Promise(resolve=>{const done=()=>{clearTimeout(timer);screen.removeEventListener('transitionend',onEnd);resolve();};const onEnd=event=>{if(event.target===screen&&event.propertyName==='opacity')done();};const timer=setTimeout(done,300);screen.addEventListener('transitionend',onEnd);screen.classList.add('loading-complete');});
 }
 screen?.remove();app.removeAttribute('aria-hidden');app.inert=!!dialog;
}
async function boot(){loading=true;app=document.querySelector('#app');dialogRoot=document.querySelector('#dialog-root');try{try{settings={reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,...JSON.parse(readStorage(UI_KEY)||'{}')};}catch{}document.documentElement.classList.toggle('motion-reduced',settings.reducedMotion);await preload();tabId=globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2);claim();reloadGame();completionWasShown=chapterComplete(vm);shell();readHash();render(true);document.addEventListener('click',onClick);document.addEventListener('keydown',onKey);document.addEventListener('change',importFile);document.addEventListener('visibilitychange',onVisibility);window.addEventListener('storage',onStorage);window.addEventListener('hashchange',()=>{rememberScene();closeDialog(true);readHash();render(true);window.scrollTo({top:0,behavior:'instant'});});window.addEventListener('popstate',()=>{if(settling){dialogHistory=!!history.state?.forestDialog;return;}if(dialog)closeDialog(true);});window.addEventListener('pagehide',()=>{if(ownsLease()&&!settling){if(!document.hidden&&hiddenAt===null){flushActive();if(!settling)save();}if(!settling)try{localStorage.removeItem(LEASE_KEY);}catch{}}});window.addEventListener('pageshow',event=>{if(event.persisted&&!settling){hiddenAt=null;storageIssue='';if(claim()){reloadGame();render(true);settlePending();}else render();}});leaseTimer=setInterval(()=>{if(ownsLease()){if(!writeStorage(LEASE_KEY,JSON.stringify({id:tabId,until:now()+7000})))render();}else if(!readOnly){readOnly=true;render();}},2000);await finishLoading();loading=false;booted=true;settlePending();tickTimer=setInterval(step,200);}catch(error){const label=document.querySelector('#loading-label');if(label)label.textContent='家园还没准备好：'+error.message+' 已有存档不会被删除。';const retry=document.querySelector('#loading-retry');if(retry){retry.hidden=false;retry.onclick=()=>location.reload();}document.documentElement.classList.add('motion-reduced');}}
if(typeof document!=='undefined'&&document.querySelector('#app'))boot();
